using System.Collections;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "FrenzyEffect", menuName = "Data/Battle/Effects/Cellarius/Frenzy Effect")]
public class FrenzyEffect : Effect
{
	[SerializeField]
	private PlayerEffectsList playerEffectsList;

	public override int ActivateEffect(int amount, GameObject effectOwner)
	{
		UnitEffects component = effectOwner.GetComponent<UnitEffects>();
		ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(FrenzyCoroutine(component));
		ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
		return amount;
	}

	private IEnumerator FrenzyCoroutine(UnitEffects unitEffects)
	{
		yield return new WaitForSeconds(0.2f);
		unitEffects.IsEffectActiveRemoveEffect(this, activateFeedback: false);
		unitEffects.AddEffect(playerEffectsList.FrenzyActiveEffect, EffectsValues.NO_VALUE);
		yield return new WaitForSeconds(0.6f);
	}
}
